#pragma once

// Reader for the embedded test vector blob. See test/data/TEST_VECTORS_FORMAT.md.

#include <RobotRaconteur/DataTypes.h>

#include <boost/cstdint.hpp>

#include <cstddef>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

namespace RobotRaconteurTest
{

// Defined by the source file generated by rr_test_embed_binary()
extern const unsigned char test_vectors_data[];
extern const std::size_t test_vectors_data_size;

namespace detail
{
inline uint32_t TestVectorsReadUInt32(std::size_t offset)
{
    return static_cast<uint32_t>(test_vectors_data[offset]) |
           (static_cast<uint32_t>(test_vectors_data[offset + 1]) << 8) |
           (static_cast<uint32_t>(test_vectors_data[offset + 2]) << 16) |
           (static_cast<uint32_t>(test_vectors_data[offset + 3]) << 24);
}
} // namespace detail

// Returns a copy of the named vector. T must match the type stored in the blob.
template <typename T>
std::vector<T> GetTestVector(const std::string& name)
{
    const std::size_t header_size = 24;
    const std::size_t entry_size = 64;
    const std::size_t name_size = 48;

    if (test_vectors_data_size < header_size || std::memcmp(test_vectors_data, "RRTVECTS", 8) != 0)
    {
        throw std::runtime_error("Invalid test vector blob");
    }
    if (detail::TestVectorsReadUInt32(8) != 1 || detail::TestVectorsReadUInt32(12) != entry_size ||
        detail::TestVectorsReadUInt32(20) != test_vectors_data_size)
    {
        throw std::runtime_error("Unsupported or truncated test vector blob");
    }

    const uint32_t entry_count = detail::TestVectorsReadUInt32(16);
    if (header_size + static_cast<boost::uint64_t>(entry_count) * entry_size > test_vectors_data_size)
    {
        throw std::runtime_error("Truncated test vector index");
    }

    for (uint32_t i = 0; i < entry_count; i++)
    {
        const std::size_t entry = header_size + i * entry_size;
        std::string entry_name;
        for (std::size_t j = 0; j < name_size && test_vectors_data[entry + j] != 0; j++)
        {
            entry_name.push_back(static_cast<char>(test_vectors_data[entry + j]));
        }
        if (entry_name != name)
        {
            continue;
        }

        if (detail::TestVectorsReadUInt32(entry + 48) !=
            static_cast<uint32_t>(RobotRaconteur::RRPrimUtil<T>::GetTypeID()))
        {
            throw std::runtime_error("Test vector type mismatch: " + name);
        }
        const uint32_t count = detail::TestVectorsReadUInt32(entry + 52);
        const uint32_t offset = detail::TestVectorsReadUInt32(entry + 56);
        const boost::uint64_t byte_count = static_cast<boost::uint64_t>(count) * sizeof(T);
        if (offset + byte_count > test_vectors_data_size)
        {
            throw std::runtime_error("Test vector out of bounds: " + name);
        }

        std::vector<T> result(count);
        if (count != 0)
        {
            // The blob is little-endian, as are all platforms Robot Raconteur supports
            std::memcpy(&result[0], test_vectors_data + offset, static_cast<std::size_t>(byte_count));
        }
        return result;
    }

    throw std::runtime_error("Test vector not found: " + name);
}

// Returns a new RRArray holding the named vector. T must match the type stored in the blob.
template <typename T>
RR_INTRUSIVE_PTR<RobotRaconteur::RRArray<T> > GetTestRRArray(const std::string& name)
{
    return RobotRaconteur::VectorToRRArray<T>(GetTestVector<T>(name));
}

} // namespace RobotRaconteurTest
